auto fp_b = filament::math::fp<1, 5, 8 >::fromf(f);
auto fp_c = filament::math::fp<1, 5, 5 >::fromf(f);

// Also a very small mantissa to tick different rounding behavior.
auto fp_d = filament::math::fp<1, 5, 2 >::fromf(f);

// Touch the results to avoid optimization away; round-trip through tof() locally.
(void) filament::math::fp<1, 5, 10>::tof(fp_a);
(void) filament::math::fp<1, 5, 8 >::tof(fp_b);
(void) filament::math::fp<1, 5, 5 >::tof(fp_c);
(void) filament::math::fp<1, 5, 2 >::tof(fp_d);

